function adapt(input, solve, kit) {
  const [arr, spec] = input;
  const rule = spec === 'plusIndex' ? (n, i) => n + i
    : spec === 'index' ? (n, i) => i
    : 'plus' in spec ? (n) => n + spec.plus
    : 'times' in spec ? (n) => n * spec.times
    : 'mod' in spec ? (n) => n % spec.mod
    : () => spec.constant;
  const fn = (n, i) => {
    const value = rule(n, i);
    kit.trace(`fn(${n}, ${i}) returns ${value}`);
    return value;
  };
  // The problem asks for a solution without the built-in map. Only calls on arr or with fn are refused,
  // because the app's own tools keep using map on their arrays while your code runs.
  const builtIn = Array.prototype.map;
  Array.prototype.map = function (callback, ...rest) {
    if (this === arr || callback === fn) throw new Error('Solve it without the built-in Array.prototype.map.');
    return builtIn.call(this, callback, ...rest);
  };
  let result;
  try {
    result = solve(arr, fn);
  } finally {
    Array.prototype.map = builtIn;
  }
  if (!Array.isArray(result)) throw new Error('map must return an array.');
  if (result === arr) throw new Error('map must return a new array, not arr itself.');
  return result;
}

