function map(arr, fn) {
  // Fill a pre-sized array from the last index down; slot i gets fn(arr[i], i) whatever the order.
  const result = new Array(arr.length);
  for (let index = arr.length - 1; index >= 0; index--) {
    result[index] = fn(arr[index], index);
  }
  return result;
}

