function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const length = small ? Math.floor(rand() * 7) : 1000;
  const top = small ? 6 : 1000000000;
  const arr = Array.from({ length }, () => Math.floor(rand() * (2 * top + 1)) - top);
  const number = () => Math.floor(rand() * (2 * top + 1)) - top;
  const kind = pick(['plus', 'times', 'mod', 'constant', 'plusIndex', 'index']);
  if (kind === 'plusIndex' || kind === 'index') return [arr, kind];
  if (kind === 'plus') return [arr, { plus: number() }];
  if (kind === 'times') return [arr, { times: Math.floor(rand() * (small ? 7 : 2001)) - (small ? 3 : 1000) }];
  if (kind === 'mod') return [arr, { mod: pick([1, 2, 3, -3, 7, small ? 4 : 1000]) }];
  return [arr, { constant: number() }];
}
